const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const { createAdapter } = require('@socket.io/redis-adapter');
const { Redis } = require('ioredis');
const jwt = require('jsonwebtoken');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const pub = new Redis(process.env.REDIS_PUB_URL);
const sub = new Redis(process.env.REDIS_SUB_URL);
io.adapter(createAdapter(pub, sub));

const tenantStreamNsp = io.of(/^\/tenant-stream\/[0-9a-f-]+$/);

tenantStreamNsp.use((socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) return next(new Error('Token missing'));

  try {
    const user = jwt.verify(token, process.env.JWT_SECRET);
    const targetTenantId = socket.nsp.name.replace('/tenant-stream/', '');

    // Enforce tenant boundary on socket namespace connection
    if (!user.tenantId || user.tenantId !== targetTenantId) {
      return next(new Error('Access denied: cross-tenant connection rejected'));
    }

    socket.data.user = user;
    next();
  } catch {
    next(new Error('Unauthorized'));
  }
});

tenantStreamNsp.on('connection', (socket) => {
  const tenantId = socket.nsp.name.replace('/tenant-stream/', '');

  const paymentChannel = `tenant:${tenantId}:payments`;
  const redisSub = sub.duplicate();
  redisSub.subscribe(paymentChannel);

  redisSub.on('message', (channel, message) => {
    socket.emit('transaction_event', JSON.parse(message));
  });

  socket.on('disconnect', () => {
    redisSub.disconnect();
  });
});

server.listen(4002);
